// Concrete slot choices and conservation; never a free-form stat/potency editor (docs/design/farm-kitchen-rework.md#8-cookbook-and-kitchen-jobs).
import { farmExactKeys, farmFailure, farmRecord, farmSafeId, farmSafeInteger, farmSuccess, type FarmResult } from './rules'
import type { FarmCatalogue, FarmInventory, FarmItemAmount } from './types'

export function resolveFarmInputs(catalogue: FarmCatalogue, recipeId: string, quantity: number,
  choices: Readonly<Record<string, string>>): FarmResult<FarmItemAmount[]> {
  const recipe = catalogue.recipesById.get(recipeId)
  if (!recipe) return farmFailure('unknown-recipe', recipeId)
  if (!farmSafeInteger(quantity, 1) || quantity > recipe.maxQuantity || !farmRecord(choices) ||
    !farmExactKeys(choices, recipe.inputs.map(slot => slot.id))) return farmFailure('invalid', 'Quantity/input slots')
  const totals = new Map<string, number>()
  for (const slot of recipe.inputs) {
    const itemId = choices[slot.id]
    const food = typeof itemId === 'string' ? catalogue.foodsById.get(itemId) : undefined
    if (!food || food.stage !== slot.stage || food.stat !== slot.stat || food.block !== recipe.block ||
      (slot.fixedItemId !== null && food.id !== slot.fixedItemId)) return farmFailure('wrong-ingredient', slot.id)
    const amount = (totals.get(food.id) ?? 0) + slot.amount * quantity
    if (!farmSafeInteger(amount, 1)) return farmFailure('invalid', 'Input overflow')
    totals.set(food.id, amount)
  }
  return farmSuccess([...totals].sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([itemId, amount]) => ({ itemId, amount })))
}

export function applyFarmInventory(inventory: FarmInventory, debits: readonly FarmItemAmount[],
  credits: readonly FarmItemAmount[]): FarmResult<Record<string, number>> {
  if (!farmRecord(inventory) || Object.entries(inventory).some(([id, n]) => !farmSafeId(id) || !farmSafeInteger(n))) return farmFailure('invalid', 'Inventory amount/id')
  const next = { ...inventory }
  for (const debit of debits) {
    if (!farmSafeId(debit.itemId) || !farmSafeInteger(debit.amount, 1)) return farmFailure('invalid', 'Inventory debit')
    if (!Object.hasOwn(next, debit.itemId) || next[debit.itemId]! < debit.amount) {
      return farmFailure('insufficient-stock', debit.itemId)
    }
    next[debit.itemId] = next[debit.itemId]! - debit.amount
  }
  for (const credit of credits) {
    if (!farmSafeId(credit.itemId)) return farmFailure('invalid', 'Inventory credit')
    const amount = (Object.hasOwn(next, credit.itemId) ? next[credit.itemId]! : 0) + credit.amount
    if (!farmSafeInteger(credit.amount, 1) || !farmSafeInteger(amount)) return farmFailure('invalid', 'Inventory overflow')
    next[credit.itemId] = amount
  }
  return farmSuccess(next)
}
